SELECT l.id,l.macro_id,l.grant_id,l.grant_generation,l.sync_generation, l.provider_tenant_id,l.provider_mailbox_id,l.disconnect_requested_at, EXISTS(SELECT 1 FROM macro_user_links e WHERE e.link_id = l.id AND e.primary_macro_id = $4 AND e.child_macro_id = l.macro_id) AS "actor_has_access!" FROM email_links l WHERE l.provider = 'OUTLOOK' AND ((l.provider_tenant_id = $1 AND l.provider_mailbox_id = $2) OR lower(l.email_address) = lower($3)) ORDER BY (l.provider_tenant_id = $1 AND l.provider_mailbox_id = $2) DESC NULLS LAST,l.id LIMIT 1 FOR UPDATE OF l
